/// semantics).
Future<void> _settleRun() async {
  try {
    await _processEvent(const AgentSettledEvent());
  } finally {
    // A throwing settled listener must not strand the run: the idle
    // completer and runtime state are always settled.
    _finishRun();
  }
}

void _finishRun() {
  _disarmRunWatchdog();
