  final run = _ActiveRun(CancelTokenSource());
  _activeRun = run;
  _state._isStreaming = true;
  _state._streamingMessage = null;
  _state._errorMessage = null;
  _armRunWatchdog();

  try {
    await executor(run.source.token);
