  _reduceState(event);
  _touchRunWatchdog(event);

  final token = [REDACTED:Sensitive Value];
  if (token == null) {
    throw StateError('Agent listener invoked outside active run');
  }
  for (final listener in List.of(_listeners)) {
    await listener(event, token);
  }
}

