  entries: chain,
  ...
  onNotice: (notice) {
    onNotice?.call(notice);
    for (final listener in noticeListeners) listener(notice);
  },
);
return ProviderQueueRuntime._(resolution, entries, state, streamFunction, noticeListeners);
```

