  String? baseUrl,
  String? apiKeyEnv = 'K_API_KEY',
}) => ProviderQueueEntry(
  providerType: kind,
  model: model,
  baseUrl: baseUrl,
  apiKeyEnv: apiKeyEnv,
);

Map<String, String> _secrets([Map<String, String> extra = const {}]) => {
  'K_API_KEY': 'key-head',
  'K2_API_KEY': 'key-two',
  'K3_API_KEY': 'key-three',
  ...extra,
};

