      reason: 'session persisted',
    );
    io.sendLine('start');
    await waitForIt(() => !cli.isBusy, reason: 'run completed');
    io.sendLine('/exit');
    await run;

    expect(cli.agent.state.model.id, 'queue-a');
  });
}
"}

