  String model, {
  String? baseUrl,
  String? apiKeyEnv = 'K_API_KEY',
}) => ProviderQueueEntry(
  providerType: kind,
  model: model,
  baseUrl: baseUrl,
  apiKeyEnv: apiKeyEnv,
);

