+(Duration, String)? explicitStreamIdleForModel(Model model) {
+  final scoped = model.streamIdleTimeout;
+  if (scoped != null) {
+    return (scoped, model.timeoutScopeLabel ?? 'model override');
+  }
+  final url = Uri.tryParse(model.baseUrl);
