          ),
        ],
        notices: const [],
      ),
      secrets: const {'K_A': 'a'},
      streamFactory: failoverFactory(),
    );
    final cli = AgentCli(
      config: AgentCliConfig(
        model: testModel,
        apiKey: '[REDACTED:Sensitive Value]',
        env: env,
        sessionRoot: '/sessions',
        providersQueueRuntime: runtime,
      ),
      io: io,
