  test('no failover: the boot-time entry stays (the sync is a no-op)', () async {
    final runtime = ProviderQueueRuntime.build(
      ProviderQueueResolution(
        scope: ProviderQueueScope.env,
        entries: [
          ProviderQueueEntry(
            providerType: 'anthropic',
            model: 'queue-a',
            apiKeyEnv: 'K_A',
            baseUrl: 'https://a.test/v1',
          ),
        ],
        notices: const [],
      ),
      secrets: const {'K_A': 'a'},
