/// Scripted [StreamFunction] replaying pre-recorded turns.
class FakeStreamFunction {
  FakeStreamFunction(this.turns);

  final List<List<AssistantMessageEvent>> turns;
  final contexts = <Context>[];
  final models = <Model>[];

