/// In-memory [SecureKeyStore] with a toggleable availability flag.
class FakeSecureKeyStore implements SecureKeyStore {
  FakeSecureKeyStore({this.available = true});

  bool available;
  bool failWrites = false;
  final map = <String, String>{};

