            apiKeyEnv: 'K_A',
            baseUrl: 'https://a.test/v1',
          ),
        ],
        notices: const [],
      ),
      secrets: const {'K_A': 'a'},
      streamFactory: failoverFactory(),
    );
    final cli = AgentCli(
